TEST 06 — Loading State Condition (Screen 2)
    Start Browser
    ${user}=    Set Variable    %{PQA_user=${user}}
    ${page}=    Set Variable    %{PQA_page=${page}}
    ${t_n}=    Set Variable    %{PQA_t_n=${t_n}}
    ${h__t_n}=    Set Variable    %{PQA_h__t_n=${h__t_n}}
    ${expected}=    Set Variable    %{PQA_expected=${expected}}
    ${role}=    Set Variable    %{PQA_role=${role}}
    ${lang}=    Set Variable    %{PQA_lang=${lang}}
    ${attr}=    Set Variable    %{PQA_attr=${attr}}
    ${fileName}=    Set Variable    %{PQA_fileName=${fileName}}

    # ⚠ TODO: Set the starting URL (go to Settings tab to configure)
    ${PQA_URL}=    Site URL    https://your-url-here.com
    Go To    ${PQA_URL}

    # Step 1: execute script — Go to Screen 2
    Set Test Variable    \${PQA_AT}    Step 1: execute script — Go to Screen 2
    Execute Javascript    showScreen(2, document.querySelectorAll('nav button')[1])
    Sleep    0.5

    # Step 2: wait
    Set Test Variable    \${PQA_AT}    Step 2: wait
    Sleep    0.3

    # Step 3: click — Click: Reset loading state
    Set Test Variable    \${PQA_AT}    Step 3: click — Click: Reset loading state
    ${el3}=    Find Element    css:#screen2 .section:last-child .btn-ghost    text:button:Reset    clickable=${True}
    Click Element    ${el3}
    Sleep    0.5

    # Step 4: wait
    Set Test Variable    \${PQA_AT}    Step 4: wait
    Sleep    0.3

    # Step 5: click — Click: Simulate Load (1.5s)
    Set Test Variable    \${PQA_AT}    Step 5: click — Click: Simulate Load (1.5s)
    ${el5}=    Find Element    css:#screen2 button.btn-primary:last-of-type    text:button:Simulate Load (1.5s)    clickable=${True}
    Click Element    ${el5}
    Sleep    0.5

    # Step 6: condition — elementVisible — IF spinner visible → skip 1 (wait for it to disappear)
    Set Test Variable    \${PQA_AT}    Step 6: condition — elementVisible — IF spinner visible → skip 1 (wait for it to disappear)
    ${ok6}=    Check Condition    elementVisible    ${EMPTY}    id:loadingSpinner    css:#loadingSpinner
    IF    $ok6
        # Step 7: wait — [SKIPPED] Short wait — skipped because spinner is showing
        Set Test Variable    \${PQA_AT}    Step 7: wait — [SKIPPED] Short wait — skipped because spinner is showing
        Sleep    0.3

    END

    # Step 9: wait — Wait 2s for load to complete
    Set Test Variable    \${PQA_AT}    Step 9: wait — Wait 2s for load to complete
    Sleep    2

    # Step 10: read DOM → "loadedResult" — Read DOM: loaded result → ${loadedResult}
    Set Test Variable    \${PQA_AT}    Step 10: read DOM → "loadedResult" — Read DOM: loaded result → \${loadedResult}
    ${el10}=    Find Element    id:loadedValue    css:#loadedValue
    ${loadedResult}=    Read Value    ${el10}    text    ${EMPTY}
    Sleep    0.5

    # Step 11: condition — elementVisible — Assert: #loadedContent is visible (skip 0 = no-op assert)
    Set Test Variable    \${PQA_AT}    Step 11: condition — elementVisible — Assert: #loadedContent is visible (skip 0 = no-op assert)
    ${ok11}=    Check Condition    elementVisible    ${EMPTY}    id:loadedContent    css:#loadedContent
    IF    $ok11
        No Operation
    END


