    [Arguments]    @{locators}
    FOR    ${loc}    IN    @{locators}
        IF    $loc.startswith('text:')
            ${tag}    ${text}=    Evaluate    $loc[5:].split(':', 1)
            ${el}=    Execute Javascript    ${PQA_FIND_TEXT_JS}    ARGUMENTS    ${text}    ${tag}
        ELSE
            ${status}    ${found}=    Run Keyword And Ignore Error    Get WebElements    ${loc}
